// ***************
// Filename: gpio_top.sv
// Author: FPGA Cores 4 U
// Description: gpio with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map gpio_regs (u_regs,
//   src/include/gpio_regs.sv, ID "GPIO", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic gpio (u_core, src/gpio.sv), joined by
//   their register ports (cfg_* to the logic, sts_* back). Generated by
//   ip/scripts/regmap_gen.py from gpio_regs.json and the ports of gpio:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-12
module gpio_top #(
  parameter int WIDTH = 16
) (
  input  logic             aclk,
  input  logic             aresetn,
  input  logic [7:0]       s_axil_awaddr,
  input  logic             s_axil_awvalid,
  output logic             s_axil_awready,
  input  logic [31:0]      s_axil_wdata,
  input  logic [3:0]       s_axil_wstrb,
  input  logic             s_axil_wvalid,
  output logic             s_axil_wready,
  output logic [1:0]       s_axil_bresp,
  output logic             s_axil_bvalid,
  input  logic             s_axil_bready,
  input  logic [7:0]       s_axil_araddr,
  input  logic             s_axil_arvalid,
  output logic             s_axil_arready,
  output logic [31:0]      s_axil_rdata,
  output logic [1:0]       s_axil_rresp,
  output logic             s_axil_rvalid,
  input  logic             s_axil_rready,
  input  logic [WIDTH-1:0] gpio_i,
  output logic [WIDTH-1:0] gpio_o,
  output logic [WIDTH-1:0] gpio_t,
  output logic             irq_o
);
  // register ports between the register map and the logic
  logic [WIDTH-1:0] cfg_out;
  logic cfg_out_wr;
  logic [WIDTH-1:0] sts_out;
  logic [WIDTH-1:0] cfg_dir;
  logic [WIDTH-1:0] sts_in;
  logic [WIDTH-1:0] cfg_set;
  logic cfg_set_wr;
  logic [WIDTH-1:0] cfg_clear;
  logic cfg_clear_wr;
  logic [WIDTH-1:0] cfg_toggle;
  logic cfg_toggle_wr;
  logic [WIDTH-1:0] cfg_int_en;
  logic [WIDTH-1:0] cfg_rise_en;
  logic [WIDTH-1:0] cfg_fall_en;
  logic [WIDTH-1:0] cfg_int_status;
  logic [WIDTH-1:0] sts_int_status_set;

  gpio_regs #(
    .WIDTH(WIDTH)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .out_o(cfg_out),
    .out_wr_o(cfg_out_wr),
    .out_i(sts_out),
    .dir_o(cfg_dir),
    .dir_wr_o(),
    .in_i(sts_in),
    .set_o(cfg_set),
    .set_wr_o(cfg_set_wr),
    .clear_o(cfg_clear),
    .clear_wr_o(cfg_clear_wr),
    .toggle_o(cfg_toggle),
    .toggle_wr_o(cfg_toggle_wr),
    .int_en_o(cfg_int_en),
    .int_en_wr_o(),
    .rise_en_o(cfg_rise_en),
    .rise_en_wr_o(),
    .fall_en_o(cfg_fall_en),
    .fall_en_wr_o(),
    .int_status_o(cfg_int_status),
    .int_status_wr_o(),
    .int_status_set_i(sts_int_status_set)
  );
  gpio #(
    .WIDTH(WIDTH)
  ) u_core (
    .aclk,
    .aresetn,
    .gpio_i,
    .gpio_o,
    .gpio_t,
    .irq_o,
    .cfg_out,
    .cfg_out_wr,
    .sts_out,
    .cfg_dir,
    .sts_in,
    .cfg_set,
    .cfg_set_wr,
    .cfg_clear,
    .cfg_clear_wr,
    .cfg_toggle,
    .cfg_toggle_wr,
    .cfg_int_en,
    .cfg_rise_en,
    .cfg_fall_en,
    .cfg_int_status,
    .sts_int_status_set
  );
endmodule
